//! The canonical serialization, hash, and project form against the TypeScript
//! (tests/vectors/canonical-vectors.json, generated by
//! tests/vectors/generate-canonical-vectors.ts from canonical-json.ts,
//! compositions.ts, and patch.ts).

use std::path::PathBuf;

use pm_model::Document;
use pm_model::canonical::{
    COMP_FIELDS, canonical_path, canonical_project, normalize_compositions, realize_patches,
    realize_project, rotate_project,
};
use pm_model::hash::canonical_hash;
use pm_model::json::{JsString, Value, parse, to_canonical_string};
use pm_model::patch::{Patch, PathPart, apply_patches, patches_from_value};

fn manifest() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn repo() -> PathBuf {
    manifest().join("../../..")
}

fn vectors() -> Value {
    parse(include_str!("vectors/canonical-vectors.json")).unwrap()
}

fn text(v: &Value) -> String {
    v.as_str().unwrap().to_owned()
}

fn load_project(entry: &Value) -> Value {
    let name = text(entry.get("name").unwrap());
    match entry.get("project").unwrap() {
        Value::String(s) => parse(&s.to_string_lossy()).unwrap(),
        _ => {
            let path = manifest().join("tests/fixtures/corpus").join(&name);
            parse(&std::fs::read_to_string(&path).unwrap()).unwrap()
        }
    }
}

fn hash_or_null(v: &Value) -> Value {
    Value::from(canonical_hash(v))
}

/// The array literal assigned to `name` in a TypeScript source file.
fn ts_string_array(source: &str, name: &str) -> Vec<String> {
    let start = source
        .find(name)
        .unwrap_or_else(|| panic!("{name} not found"));
    let rest = &source[start..];
    let open = rest.find('[').unwrap();
    let close = rest.find(']').unwrap();
    rest[open + 1..close]
        .split(',')
        .map(|s| s.trim().trim_matches('\'').trim_matches('"').to_owned())
        .filter(|s| !s.is_empty())
        .collect()
}

#[test]
fn comp_fields_match_both_typescript_lists() {
    let expected: Vec<String> = COMP_FIELDS.iter().map(|s| s.to_string()).collect();
    let compositions = std::fs::read_to_string(
        repo().join("apps/desktop/src/renderer/src/legacy/core/compositions.ts"),
    )
    .unwrap();
    assert_eq!(
        ts_string_array(&compositions, "export const COMP_FIELDS"),
        expected
    );
    let canonical_json =
        std::fs::read_to_string(repo().join("apps/desktop/src/shared/canonical-json.ts")).unwrap();
    assert_eq!(
        ts_string_array(&canonical_json, "export const CANONICAL_COMP_FIELDS"),
        expected
    );
    let from_vectors: Vec<String> = vectors()
        .get("compFields")
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .map(text)
        .collect();
    assert_eq!(from_vectors, expected);
}

#[test]
fn serialization_matches_canonical_json_ts() {
    for case in vectors().get("serialization").unwrap().as_array().unwrap() {
        let value = parse(&text(case.get("source").unwrap())).unwrap();
        assert_eq!(
            to_canonical_string(&value),
            text(case.get("canonical").unwrap())
        );
        assert_eq!(canonical_hash(&value), text(case.get("hash").unwrap()));
    }
}

#[test]
fn project_forms_match_typescript() {
    let vectors = vectors();
    let entries = vectors.get("projects").unwrap().as_array().unwrap();
    assert!(entries.len() >= 30);
    for entry in entries {
        let name = text(entry.get("name").unwrap());
        let project = load_project(entry);
        let canonical = canonical_project(project.clone());
        if let Some(Value::String(expected)) = entry.get("canonical") {
            assert_eq!(
                to_canonical_string(&canonical),
                expected.to_string_lossy(),
                "{name}"
            );
        }
        assert_eq!(
            canonical_hash(&canonical),
            text(entry.get("hash").unwrap()),
            "{name}: canonical form"
        );
        let realized = realize_project(canonical.clone());
        assert_eq!(
            hash_or_null(&realized),
            *entry.get("realized").unwrap(),
            "{name}: realized"
        );
        for (id, expected) in entry.get("rotations").unwrap().as_object().unwrap() {
            let rotated = rotate_project(project.clone(), id);
            assert_eq!(
                hash_or_null(&rotated),
                *expected,
                "{name}: rotate to {id:?}"
            );
        }
        let mut counter = 0;
        let mut normalized = project.clone();
        normalize_compositions(&mut normalized, |prefix| {
            counter += 1;
            format!("{prefix}-test-{counter}")
        });
        assert_eq!(
            hash_or_null(&normalized),
            *entry.get("normalized").unwrap(),
            "{name}: normalized"
        );
        // Well-formed projects round-trip exactly through the canonical form.
        if pm_model::canonical::open_comp_id(&project).is_some() {
            assert_eq!(
                to_canonical_string(&realized),
                to_canonical_string(&project),
                "{name}: realize(canonical(p)) == p"
            );
        }
    }
}

/// The shadow-replay auditor: canonical patches applied to the canonical
/// mirror reproduce the renderer's canonical form, step by step, and the
/// realized patches reproduce the stored project.
#[test]
fn edit_sessions_replay_to_the_same_hashes() {
    let vectors = vectors();
    let sessions = vectors.get("sessions").unwrap().as_array().unwrap();
    assert!(!sessions.is_empty());
    let mut steps_checked = 0;
    for session in sessions {
        let name = text(session.get("name").unwrap());
        let mut stored = load_project(session);
        let mut mirror = Document::new(Some(canonical_project(stored.clone())), 0);
        for (i, step) in session
            .get("steps")
            .unwrap()
            .as_array()
            .unwrap()
            .iter()
            .enumerate()
        {
            let label = text(step.get("label").unwrap());
            let patches = patches_from_value(step.get("patches").unwrap()).unwrap();
            let expected = text(step.get("hash").unwrap());
            mirror.apply(&patches).unwrap();
            assert_eq!(
                mirror.canonical_hash().unwrap(),
                expected,
                "{name} step {i} ({label}): mirror is {}",
                to_canonical_string(&mirror.to_value().unwrap())
            );
            if label == "open composition" {
                let target = patches
                    .iter()
                    .find(|p| p.path == [PathPart::from("compId")])
                    .and_then(|p| p.value.as_ref())
                    .and_then(Value::as_js_string)
                    .cloned()
                    .unwrap_or_else(|| JsString::from(""));
                stored = rotate_project(stored, &target);
            } else {
                let realized = realize_patches(&patches, &stored);
                let mut root = Some(stored);
                apply_patches(&mut root, &realized).unwrap();
                stored = root.unwrap();
            }
            assert_eq!(
                canonical_hash(&canonical_project(stored.clone())),
                expected,
                "{name} step {i} ({label}): stored project after realizePatches"
            );
            steps_checked += 1;
        }
    }
    assert!(steps_checked >= 200);
}

#[test]
fn canonical_paths() {
    let p =
        |parts: &[&str]| -> Vec<PathPart> { parts.iter().map(|s| PathPart::from(*s)).collect() };
    assert_eq!(
        canonical_path(&p(&["layers", "0"]), Some("C1")),
        p(&["comps", "C1", "layers", "0"])
    );
    assert_eq!(
        canonical_path(&p(&["compName"]), Some("C1")),
        p(&["comps", "C1", "name"])
    );
    assert_eq!(
        canonical_path(&p(&["assets", "x"]), Some("C1")),
        p(&["assets", "x"])
    );
    assert_eq!(canonical_path(&p(&["layers"]), None), p(&["layers"]));
    assert_eq!(canonical_path(&p(&["layers"]), Some("")), p(&["layers"]));
    assert_eq!(canonical_path(&[], Some("C1")), Vec::<PathPart>::new());
}

#[test]
fn canonical_form_edge_cases() {
    // Not a project, no compId, or comps that is not an object: unchanged.
    for source in [
        "5",
        "[1]",
        r#"{"w":1}"#,
        r#"{"compId":"","w":1}"#,
        r#"{"compId":7,"w":1}"#,
        r#"{"compId":"C","w":1,"comps":[1]}"#,
    ] {
        let v = parse(source).unwrap();
        assert_eq!(
            to_canonical_string(&canonical_project(v.clone())),
            to_canonical_string(&v),
            "{source}"
        );
    }
    // No comps member: one is created; a stale open entry is replaced.
    let v = parse(r#"{"compId":"C","compName":"N","w":1,"name":"P"}"#).unwrap();
    assert_eq!(
        to_canonical_string(&canonical_project(v)),
        r#"{"compId":"C","comps":{"C":{"id":"C","name":"N","w":1}},"name":"P"}"#
    );
    let v = parse(r#"{"compId":"C","w":2,"comps":{"C":{"stale":true},"D":{"id":"D"}}}"#).unwrap();
    assert_eq!(
        to_canonical_string(&canonical_project(v)),
        r#"{"compId":"C","comps":{"C":{"id":"C","w":2},"D":{"id":"D"}}}"#
    );
    // Realizing drops members that do not belong at the top level.
    let v = parse(r#"{"compId":"C","comps":{"C":{"id":"C","name":"N","w":3,"extra":1}}}"#).unwrap();
    assert_eq!(
        to_canonical_string(&realize_project(v)),
        r#"{"compId":"C","compName":"N","comps":{},"w":3}"#
    );
    // Unrealizable canonical values come back unchanged.
    let v = parse(r#"{"compId":"C","comps":{"C":5}}"#).unwrap();
    assert_eq!(
        to_canonical_string(&realize_project(v)),
        r#"{"compId":"C","comps":{"C":5}}"#
    );
}

#[test]
fn realize_patches_for_the_open_composition() {
    let stored = parse(
        r#"{"compId":"C1","compName":"Main","w":10,"audioGain":2,"layers":[],"comps":{"C2":{"id":"C2"}}}"#,
    )
    .unwrap();
    let canonical = vec![
        Patch::set(
            vec!["comps".into(), "C1".into(), "layers".into()],
            parse(r#"[{"id":"a"}]"#).unwrap(),
        ),
        Patch::set(
            vec!["comps".into(), "C1".into(), "extra".into()],
            Value::from(1),
        ),
        Patch::set(
            vec!["comps".into(), "C2".into(), "w".into()],
            Value::from(5),
        ),
        Patch::set(
            vec!["comps".into(), "C1".into()],
            parse(r#"{"id":"C1","name":"Renamed","w":20}"#).unwrap(),
        ),
    ];
    let realized = realize_patches(&canonical, &stored);
    let mut root = Some(stored);
    apply_patches(&mut root, &realized).unwrap();
    assert_eq!(
        to_canonical_string(root.as_ref().unwrap()),
        r#"{"compId":"C1","compName":"Renamed","comps":{"C2":{"id":"C2","w":5}},"layers":[{"id":"a"}],"w":20}"#
    );
}
